// S1 bb.js probe: honest UltraHonk proof for the owned synthetic circuit, then
// bb.js (WASM) verifyProof under three encodings of the same public input:
// honest x, x + r, and x + k*r (largest k fitting in 256 bits).
// For keccak modes it also writes the proof, public inputs, VK and the
// Solidity verifier generated by the same bb.js version, for the Anvil step.
// Usage: node bbjs_probe.mjs <bb.js pkg dir> <program.json> <witness.gz> <outdir>
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const [pkg, programPath, witnessPath, outdir] = process.argv.slice(2);
const bb = await import(pathToFileURL(pkg + '/dest/node/index.js').href);
const version = JSON.parse(readFileSync(pkg + '/package.json', 'utf8')).version;
const major = Number(version.split('.')[0]);
const program = JSON.parse(readFileSync(programPath, 'utf8'));
const witness = readFileSync(witnessPath);
const api = major >= 4 ? await bb.Barretenberg.new() : undefined;
const backend = api ? new bb.UltraHonkBackend(program.bytecode, api) : new bb.UltraHonkBackend(program.bytecode);

const R = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;
const hex32 = (v) => '0x' + v.toString(16).padStart(64, '0');

// Modes: label -> options. 3.x uses the keccak/keccakZK flags; >=4 uses verifierTarget.
const modes = major >= 4
  ? { 'default': {}, 'evm': { verifierTarget: 'evm' }, 'evm-no-zk': { verifierTarget: 'evm-no-zk' } }
  : { 'default': {}, 'keccakZK': { keccakZK: true }, 'keccak': { keccak: true } };

const out = { version, modes: {} };
for (const [label, opts] of Object.entries(modes)) {
  const dir = `${outdir}/${label}`;
  mkdirSync(dir, { recursive: true });
  const rec = {};
  try {
    const proof = await backend.generateProof(witness, opts);
    const x = BigInt(proof.publicInputs[0]);
    const k = ((1n << 256n) - 1n - x) / R;
    rec.n = x.toString();
    rec.max_k = k.toString();
    rec.proof_bytes = proof.proof.length;
    rec.results = {};
    for (const [name, value] of [['honest', x], ['plus_r', x + R], ['max_k', x + k * R]]) {
      const candidate = { ...proof, publicInputs: [hex32(value), ...proof.publicInputs.slice(1)] };
      try { rec.results[name] = { input: hex32(value), accepted: await backend.verifyProof(candidate, opts) }; }
      catch (e) { rec.results[name] = { input: hex32(value), accepted: false, error: String(e.message).slice(0, 300) }; }
    }
    if (label !== 'default') {
      writeFileSync(`${dir}/proof`, proof.proof);
      writeFileSync(`${dir}/public_inputs`, Buffer.concat(proof.publicInputs.map((p) => Buffer.from(p.slice(2).padStart(64, '0'), 'hex'))));
      const vk = await backend.getVerificationKey(opts);
      writeFileSync(`${dir}/vk`, vk);
      writeFileSync(`${dir}/HonkVerifier.sol`, await backend.getSolidityVerifier(vk, opts));
    }
  } catch (e) {
    rec.error = String(e.message).slice(0, 500);
  }
  out.modes[label] = rec;
}
console.log(JSON.stringify(out, null, 2));
await backend.destroy?.();
await api?.destroy?.();
